import{_ as a,o as t,a as o,b as s}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"附录","link":"/guide/programming_guide/appendix/show_kernel_debug_data_tool"},{"text":"FAQ","link":"/guide/programming_guide/appendix/faq/kernel_precision_issue"},{"text":"算子包部署时出现权限不足报错","link":"/guide/programming_guide/appendix/faq/operator_deploy_permission_error"}]},"headers":[],"relativePath":"guide/programming_guide/appendix/faq/operator_deploy_permission_error.md","filePath":"guide/programming_guide/appendix/faq/operator_deploy_permission_error.md","outlineHeaders":[{"level":2,"title":"现象描述","slug":"现象描述","link":"#现象描述"},{"level":2,"title":"问题根因","slug":"问题根因","link":"#问题根因"},{"level":2,"title":"处理步骤","slug":"处理步骤","link":"#处理步骤"}],"lastUpdated":1786949923000}'),i={name:"guide/programming_guide/appendix/faq/operator_deploy_permission_error.md"};function n(r,e,d,p,l,c){return t(),o("div",null,[...e[0]||(e[0]=[s(`<div><article class="markdown-body"><h1>算子包部署时出现权限不足报错<span id="ZH-CN_TOPIC_0000002096022474"></span></h1><h2 id="现象描述">现象描述<span id="section151611254194612"></span><a class="header-anchor" href="#现象描述">​</a></h2><p>部署自定义算子包时，出现如下报错信息：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>[WARNING] The directory /usr/local/Ascend/cann/opp does not have sufficient permissions. Please check and modify the folder permissions (e.g., using chmod), or use the --install-path option to specify an installation path and source the generated set_env.bash.
...
[ERROR] create /usr/local/Ascend/cann/opp/vendors/customize/framework failed
</code></pre></div><h2 id="问题根因">问题根因<span id="section417961104715"></span><a class="header-anchor" href="#问题根因">​</a></h2><p>当前操作用户缺少对部署路径下vendors目录的写权限。</p><p>自定义算子包默认安装路径<code>\${INSTALL_DIR}/opp/vendors</code>的目录权限与CANN软件包安装用户和安装配置有关：root用户安装CANN，<code>\${INSTALL_DIR}/opp/vendors</code>权限为755；非root用户携带--install for all参数安装CANN，该目录权限为755，非root用户不带--install for all参数安装CANN时，该目录权限为750。</p><p>例如，root用户安装CANN软件包后，HwHiAiUser属组用户在对应目录部署自定义算子包，因为其他用户没有写权限，会出现上述报错信息，提示权限不足导致自定义算子包部署失败。</p><h2 id="处理步骤">处理步骤<span id="section12149153520416"></span><a class="header-anchor" href="#处理步骤">​</a></h2><ul><li><p>方法一：使用--install-path参数指定安装目录（参考<a href="../../advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process.html#custom-install-path">指定目录安装</a>）。运行用户需要对指定的安装路径有可读写权限。安装后执行生成的<code>set_env.bash</code>脚本，由该脚本配置算子运行时查找路径。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>./custom_opp_&lt;target os&gt;_&lt;target architecture&gt;.run --install-path=&lt;path&gt;
source &lt;path&gt;/vendors/&lt;vendor_name&gt;/bin/set_env.bash
</code></pre></div></li><li><p>方法二：联系CANN软件包安装用户修改默认安装路径下的vendors目录权限，比如修改为777：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>chmod 777 /usr/local/Ascend/cann/opp/vendors/
</code></pre></div></li></ul></article></div>`,1)])])}const g=a(i,[["render",n]]);export{_ as __pageData,g as default};
